@Test
public void testAdapterWithAspectMultipleTimes(BundleContext context) {
    DependencyManager m = new DependencyManager(context);
    // helper class that ensures certain steps get executed in sequence
    Ensure e = new Ensure();
    Component aspect1 = m.createAspectService(OriginalService.class, null, 10, null).setImplementation(ServiceAspect.class);
    Component aspect2 = m.createAspectService(OriginalService.class, null, 15, null).setImplementation(ServiceAspect.class);
    Component adapter = m.createAdapterService(OriginalService.class, null, "add", null, "remove", "swap").setInterface(AdaptedService.class.getName(), null).setImplementation(ServiceAdapter.class);
    m.add(adapter);
    m.add(aspect1);
    List originals = new ArrayList();
    List consumers = new ArrayList();
    int count = 100;
    for (int i = 0; i < count; i++) {
        // create a service provider and consumer
        Dictionary props = new Hashtable();
        props.put("number", "" + i);
        Component original = m.createComponent().setImplementation(new ServiceProvider("" + i, e)).setInterface(OriginalService.class.getName(), props);
        Component consumer = m.createComponent().setImplementation(new ServiceConsumer(e, "" + i)).add(m.createServiceDependency().setService(AdaptedService.class, "(number=" + i + ")").setCallbacks("add", null, "remove", "swap").setRequired(true));
        m.add(original);
        e.waitForStep(1 + i, 15000);
        originals.add(original);
        //	        m.add(consumer);
        consumers.add(consumer);
    }
    m.add(aspect2);
    e.waitForStep(2 + count, 15000);
    // dumpComponents(m)
    for (int i = 0; i < 1; i++) {
        for (Object original : originals) {
            m.remove((Component) original);
        }
        for (Object consumer : consumers) {
            m.remove((Component) consumer);
        }
    }
    m.remove(aspect1);
    m.remove(adapter);
    e.waitForStep(count * 3, 15000);
    m.remove(aspect2);
    e.step(count * 3 + 1);
}

