    m.add(provider);
    // add the first consumer, and wait until its updated() method is invoked
    m.add(consumer1);
    e.waitForStep(2, 15000);
    // add the second consumer, and wait until its updated() method is invoked
    m.add(consumer2);
    e.waitForStep(3, 15000);
