    assertBundleExists(getSymbolicName("bundle2"), "1.0.0");
    // Now we should be able to resolve the dependencies for bundle2...
    assertTrue(m_packageAdmin.resolveBundles(new Bundle[] { dp1.getBundle(getSymbolicName("bundle2")) }));
